const j = $json.body || $json;
return {
  json: {
    status: 'BLOCKED',
    reason: j.error || 'SUPABASE_GUARD_ERROR',
    failed_node: j.node,
    timestamp: new Date().toISOString()
  }
};

const baseUrl = ($env.SUPABASE_URL || '').trim().replace(/\/$/, '');
const serviceKey = ($env.SUPABASE_SERVICE_ROLE_KEY || '').trim();
const payload = {
  actor_type: 'SYSTEM',
  actor_external_ref: 'n8n:phase2-error-handler',
  action: 'pipeline_blocked_by_guard',
  entity_type: 'CONTENT_ITEM',
  reason: $json.reason,
  after_state: 'BLOCKED',
  metadata: { cross_phase_audit: true, intent: 'Phase 2 Error Logging via Centralized Phase 1 Audit Surface' }
};
try {
  await this.helpers.httpRequest({
    url: `${baseUrl}/rest/v1/phase1_audit_logs`,
    method: 'POST',
    headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}` },
    body: payload, json: true
  });
  return { json: { ...$json, audit_status: 'LOGGED' } };
} catch (e) {
  return { json: { ...$json, audit_status: 'FAILED', audit_error: e.message } };
}
